import { STORE_PRODUCT_CATALOG, STORE_PURCHASE_ELIGIBILITY_NOTE } from './vipConfig'
import { PREMIUM_GAME_UPGRADES } from './paidGameCatalog'
import { EYEOLEAN_STORE_PRODUCTS } from '../economy/storeCatalog'
import {
  VIP_BASE_PRICE_CENTS,
  VIP_MIN_UPGRADE_PRICE_CENTS,
  VIP_STANDALONE_NOMINAL_PRICE_CENTS,
  VIP_UPGRADE_CREDIT_RATE,
  VIP_UPGRADE_TIERS,
} from './vipUpgrade'

/** Deterministic reference generated from the catalogs used by the app. */
export function renderMarketplaceDocumentation(): string {
  const lines = [
    '# Marketplace catalog',
    '',
    '<!-- Generated by npm run generate:marketplace. Edit the source catalogs, not this file. -->',
    '',
    'Premium Challenges and VIP both unlock every premium minigame version listed below. VIP also includes every released standalone product and VIP themes.',
    '',
    'Prices shown to players come from Apple or Google. Eyeolean prices below are in-game currency.',
    '',
    STORE_PURCHASE_ELIGIBILITY_NOTE,
    '',
    '## Permanent products',
    '',
  ]
  for (const product of STORE_PRODUCT_CATALOG) {
    lines.push(
      `### ${product.title}`,
      '',
      `- Product ID: \`${product.productId}\``,
      `- Availability: ${product.availableInRelease ? 'Released' : 'Reserved; hidden from release'}`,
      `- Shelf: ${product.shelf}`,
      `- Badge: ${product.badge}`,
      `- Access: ${product.accessInstructions}`,
      '',
      product.description,
      '',
      product.shortTagline,
      '',
      product.fullDescription,
      '',
      ...product.benefits.map((benefit) => `- ${benefit}`),
      '',
      ...(product.legalNote ? [product.legalNote, ''] : [])
    )
  }
  lines.push(
    '## VIP upgrade pricing',
    '',
    `Nominal VIP price: ${(VIP_BASE_PRICE_CENTS / 100).toFixed(2)}. Standalone credit: ${VIP_UPGRADE_CREDIT_RATE * 100}%. Minimum upgrade price: ${(VIP_MIN_UPGRADE_PRICE_CENTS / 100).toFixed(2)}. These are the upgrade resolver's nominal values; checkout uses localized native-store prices.`,
    '',
    '| Standalone product | Nominal credit value |',
    '| --- | ---: |',
    ...STORE_PRODUCT_CATALOG.flatMap((product) => {
      const cents = product.entitlement
        ? VIP_STANDALONE_NOMINAL_PRICE_CENTS[product.entitlement]
        : undefined
      return cents == null ? [] : [`| ${product.title} | ${(cents / 100).toFixed(2)} |`]
    }),
    '',
    '| VIP upgrade tier | Product ID |',
    '| ---: | --- |',
    ...VIP_UPGRADE_TIERS.map(
      (tier) => `| ${(tier.priceCents / 100).toFixed(2)} | \`${tier.productId}\` |`
    ),
    '',
    '## Premium minigame versions',
    '',
    '| Game | Registry key | Upgrade | Access |',
    '| --- | --- | --- | --- |',
    ...PREMIUM_GAME_UPGRADES.map(
      (game) =>
        `| ${game.title} | \`${game.key}\` | ${game.premiumExperience ?? 'remaster'} | Premium Challenges or VIP |`
    ),
    '',
    '## Eyeolean powers',
    ''
  )
  for (const product of Object.values(EYEOLEAN_STORE_PRODUCTS)) {
    lines.push(
      `### ${product.title}`,
      '',
      product.shortDescription,
      '',
      `First purchase: ${product.price.toLocaleString('en-US')} Eyeoleans. Second purchase: ${product.secondPrice.toLocaleString('en-US')} Eyeoleans. Season caps: ${product.maxSeasonPurchases} purchases, ${product.maxSeasonUses} uses.`,
      '',
      ...Object.entries(product.modeRules).map(
        ([mode, rule]) =>
          `- ${mode}: ${rule.available ? `${rule.title}. ${rule.detail}` : rule.unavailableReason}`
      ),
      ''
    )
  }
  return lines.join('\n')
}
